52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        Collection<Owner> owners = this.clinicService.findAllOwners();
106	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
107	        if (owners.stream().anyMatch(existing -> existing.getTelephone().equals(owner.getTelephone()))
108	                || (!sharesHousehold && owners.stream().anyMatch(existing -> sameHousehold(existing, owner)))) {
109	            return new ResponseEntity<>(HttpStatus.CONFLICT);
110	        }
111	        owner.setCustomerCode(CustomerCode.of(owner.getLastName(), owners.size()));
112	        this.clinicService.saveOwner(owner);
113	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
114	        headers.setLocation(UriComponentsBuilder.newInstance()
115	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
116	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
117	    }
118	
119	    /** Two owners share a household when their last name and address match, compared
120	     *  case-insensitively with runs of whitespace collapsed to a single space. */
121	    private static boolean sameHousehold(Owner a, Owner b) {
122	        return a.getLastName().equalsIgnoreCase(b.getLastName())
123	            && a.getAddress().trim().replaceAll("\\s+", " ")
124	                .equalsIgnoreCase(b.getAddress().trim().replaceAll("\\s+", " "));
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
130	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
131	        if (currentOwner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        currentOwner.setAddress(ownerFieldsDto.getAddress());
135	        currentOwner.setCity(ownerFieldsDto.getCity());
136	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
137	        currentOwner.setLastName(ownerFieldsDto.getLastName());
138	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
139	        this.clinicService.saveOwner(currentOwner);
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Transactional
145	    @Override
146	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
147	        Owner owner = this.clinicService.findOwnerById(ownerId);
148	        if (owner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        this.clinicService.deleteOwner(owner);
152	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        HttpHeaders headers = new HttpHeaders();
163	        Pet pet = petMapper.toPet(petFieldsDto);
164	        owner.setId(ownerId);
165	        pet.setOwner(owner);
166	        pet.getType().setName(null);
167	        this.clinicService.savePet(pet);
168	        PetDto petDto = petMapper.toPetDto(pet);
169	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
170	            .buildAndExpand(pet.getId()).toUri());
171	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
177	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
178	        if (currentOwner != null) {
179	            Pet currentPet = this.clinicService.findPetById(petId);
180	            if (currentPet != null) {
181	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
182	                currentPet.setName(petFieldsDto.getName());
183	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
184	                this.clinicService.savePet(currentPet);
185	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
186	            }
187	        }
188	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
194	        HttpHeaders headers = new HttpHeaders();
195	        Visit visit = visitMapper.toVisit(visitFieldsDto);
196	        Pet pet = new Pet();
197	        pet.setId(petId);
198	        visit.setPet(pet);
199	        this.clinicService.saveVisit(visit);
200	        VisitDto visitDto = visitMapper.toVisitDto(visit);
201	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
202	            .buildAndExpand(visit.getId()).toUri());
203	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
204	    }
205	
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
210	        Owner owner = this.clinicService.findOwnerById(ownerId);
211	        if (owner != null) {
212	            Pet pet = owner.getPet(petId);
213	            if (pet != null) {
214	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
215	            }
216	        }
217	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	    }
219	}
