27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form, e.g. +61412345678")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
61	    private Set<Pet> pets;
62	
63	    /** Default an absent registration date to the server's current date on first persist. */
64	    @PrePersist
65	    void defaultRegistrationDate() {
66	        if (this.registrationDate == null) {
67	            this.registrationDate = LocalDate.now();
68	        }
69	    }
70	
71	    public LocalDate getRegistrationDate() {
72	        return this.registrationDate;
73	    }
74	
75	    public void setRegistrationDate(LocalDate registrationDate) {
76	        this.registrationDate = registrationDate;
77	    }
78	
79	    public String getCustomerCode() {
80	        return this.customerCode;
81	    }
82	
83	    public void setCustomerCode(String customerCode) {
84	        this.customerCode = customerCode;
85	    }
86	
87	    public String getEmail() {
88	        return this.email;
89	    }
90	
91	    public void setEmail(String email) {
92	        this.email = email == null ? null : email.toLowerCase();
93	    }
94	
95	    public String getAddress() {
96	        return this.address;
97	    }
98	
99	    public void setAddress(String address) {
100	        this.address = address;
101	    }
102	
103	    public String getCity() {
104	        return this.city;
105	    }
106	
107	    public void setCity(String city) {
108	        this.city = city;
109	    }
110	
111	    public String getTelephone() {
112	        return this.telephone;
113	    }
114	
115	    public void setTelephone(String telephone) {
116	        this.telephone = telephone == null ? null : PhoneNumbers.toE164(telephone);
117	    }
118	
119	    protected Set<Pet> getPetsInternal() {
120	        if (this.pets == null) {
121	            this.pets = new HashSet<>();
122	        }
123	        return this.pets;
124	    }
125	
126	    protected void setPetsInternal(Set<Pet> pets) {
127	        this.pets = pets;
128	    }
129	
130	    public List<Pet> getPets() {
131	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
132	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
133	        return Collections.unmodifiableList(sortedPets);
134	    }
135	
136	    public void setPets(List<Pet> pets) {
137	        this.pets = new HashSet<>(pets);
138	    }
139	
140	    public void addPet(Pet pet) {
141	        getPetsInternal().add(pet);
142	        pet.setOwner(this);
143	    }
144	
145	    /**
146	     * Return the Pet with the given name, or null if none found for this Owner.
147	     *
148	     * @param name to test
149	     * @return true if pet name is already in use
150	     */
151	    public Pet getPet(String name) {
152	        return getPet(name, false);
153	    }
154	
155	    /**
156	     * Return the Pet with the given name, or null if none found for this Owner.
157	     *
158	     * @param name to test
159	     * @return true if pet name is already in use
160	     */
161	    public Pet getPet(String name, boolean ignoreNew) {
162	        name = name.toLowerCase();
163	        for (Pet pet : getPetsInternal()) {
164	            if (!ignoreNew || !pet.isNew()) {
165	                String compName = pet.getName();
166	                compName = compName.toLowerCase();
167	                if (compName.equals(name)) {
168	                    return pet;
169	                }
170	            }
171	        }
172	        return null;
173	    }
174	
175	    public Pet getPet(Integer petId) {
176	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
177	    }
178	
179	    @Override
180	    public String toString() {
181	        return new ToStringCreator(this)
182	
183	            .append("id", this.getId())
184	            .append("new", this.isNew())
185	            .append("lastName", this.getLastName())
186	            .append("firstName", this.getFirstName())
187	            .append("address", this.address)
188	            .append("city", this.city)
189	            .append("telephone", this.telephone)
190	            .toString();
191	    }
192	}
